random.seed(1453)
out = []
for i, (cat, q, right, wrong, info) in enumerate(Q, 1):
    opts = [right] + wrong
    random.shuffle(opts)
    out.append((i, cat, q, opts, opts.index(right), info))

def lit(s):
    return "'" + s.replace("'", "''") + "'"

print("-- 014: Günün sorusu havuzu (supabase/sorular.py ile üretildi, elle düzenlemeyin)")
print("insert into public.quiz_questions (id, cat, q, opts, ans, info) values")
rows = [f"({i}, {lit(c)}, {lit(q)}, {lit(json.dumps(o, ensure_ascii=False))}::jsonb, {a}, {lit(inf)})" for i, c, q, o, a, inf in out]
print(",\n".join(rows))
print("on conflict (id) do update set cat = excluded.cat, q = excluded.q, opts = excluded.opts, ans = excluded.ans, info = excluded.info;")
